package web

import (
	"net/http"

	"github.com/a-h/templ"
	"github.com/alexedwards/scs/v2"
	"github.com/raffy-io/taskifyv3/internal/shared"

	"github.com/justinas/nosurf"
)

type Renderer struct {
    SessionManager *scs.SessionManager
}

func NewRenderer(sm *scs.SessionManager) *Renderer {
    return &Renderer{SessionManager: sm}
}

func (rd *Renderer) Render(w http.ResponseWriter, r *http.Request, component templ.Component) error {
    // Extract the nosurf token generated by the middleware for this request
    csrfToken := nosurf.Token(r)

    w.Header().Set("Content-Type", "text/html; charset=utf-8")
    

	// Base layout is inside internal/shared view.templ
    layout := shared.Base(csrfToken, component)
    return layout.Render(r.Context(), w)
}

//-- make sure to include this in the body tag of layout --//
// hx-headers='{"X-CSRF-Token": document.querySelector("meta[name=\'csrf-token\']").content}'